## Code Example

```javascript
// Node.js Azure Function skeleton for upsert
module.exports = async function (context, req) {
  const tenantId = req.query.tenantId || (req.body && req.body.tenantId);
  const flags = req.body?.flags;
  if (!tenantId || !flags) return { status: 400, body: 'Missing tenantId or flags' };
  const container = cosmosClient.database(dbName).container('FeatureFlags');
  const item = { id: 'flags', tenantId, flags, _etag: undefined };
  const { resource: stored } = await container.items.upsert(item);
  context.res = { status: 200, body: stored };
};
```

